import java.text.SimpleDateFormat

def sdf = new SimpleDateFormat("HHmm")

// 1. PADDING ORARI: Aggiunge gli zeri a sinistra
def timeFields = ["DEP_TIME", "CRS_DEP_TIME", "ARR_TIME", "CRS_ARR_TIME"]
timeFields.each { field ->
    def val = record.getAsString(field)
    if (val != null && val.trim().length() > 0) {
        // Se c'è una stringa anomala "2400.0" la tronca a "2400", altrimenti fa solo il padding
        val = val.contains(".") ? val.substring(0, val.indexOf(".")) : val
        record.setValue(field, val.trim().padLeft(4, '0'))
    }
}

// 2. CORREZIONE ANOMALIE: Porta a 0 i ritardi negativi
def delayFields = ["CARRIER_DELAY", "WEATHER_DELAY", "NAS_DELAY", "SECURITY_DELAY", "LATE_AIRCRAFT_DELAY"]
delayFields.each { field ->
    def val = record.getValue(field)
    if (val != null && ((Number) val).doubleValue() < 0) {
        record.setValue(field, 0.0d)
    }
}

// 3. CALCOLO RITARDI MANCANTI (Con gestione mezzanotte)
def calcDelay = { actualStr, scheduledStr ->
    // Controllo di sicurezza: se mancano o non sono lunghi 4 caratteri, scarta il calcolo
    if (!actualStr || !scheduledStr || actualStr.length() != 4 || scheduledStr.length() != 4) return null

    try {
        int aH = actualStr.substring(0, 2).toInteger()
        int aM = actualStr.substring(2, 4).toInteger()
        int sH = scheduledStr.substring(0, 2).toInteger()
        int sM = scheduledStr.substring(2, 4).toInteger()

        // Nel mondo dell'aviazione la mezzanotte è spesso scritta come 2400. La convertiamo in 0000.
        if (aH == 24) { aH = 0; aM = 0 }
        if (sH == 24) { sH = 0; sM = 0 }

        int actualMins = (aH * 60) + aM
        int schedMins = (sH * 60) + sM

        double diff = actualMins - schedMins

        // Gestione asimmetrica dello scavallamento della mezzanotte
        // Assumiamo che un volo possa partire al massimo con 2 ORE di anticipo (-120 min)
        // e con un ritardo massimo di 22 ORE (+1320 min)
        if (diff < -120) {
            diff += 1440.0 // Il volo era atteso alle 23:50 ed è partito alle 00:15 (diff grezza: -1415 -> +25)
        } else if (diff > 1320) {
            diff -= 1440.0 // Il volo era atteso alle 00:10 ed è partito alle 23:55 (diff grezza: +1425 -> -15)
        }

        return diff
    } catch (Exception e) {
        return null // Protezione totale da stringhe impreviste ("abcd")
    }
}

def cancelled = record.getValue("CANCELLED")
if (cancelled != null && ((Number) cancelled).doubleValue() == 0.0) {

    if (record.getValue("DEP_DELAY") == null) {
        def delay = calcDelay(record.getAsString("DEP_TIME"), record.getAsString("CRS_DEP_TIME"))
        if (delay != null) record.setValue("DEP_DELAY", delay)
    }

    if (record.getValue("ARR_DELAY") == null) {
        def delay = calcDelay(record.getAsString("ARR_TIME"), record.getAsString("CRS_ARR_TIME"))
        if (delay != null) record.setValue("ARR_DELAY", delay)
    }
}

return record
